/**
 * Not committed. Measures cache write/read per step for three continuity
 * designs on the operator's own Claude Code installation, driving the Agent SDK
 * the way `src/adapter.ts` does.
 *
 * Run: pnpm exec tsx packages/llm/llm-claude-code/tmp/probe.ts [A|B|C]
 */

import { execFileSync } from 'node:child_process'
import { query, type Options, type SDKMessage, type SDKUserMessage } from '@anthropic-ai/claude-agent-sdk'
import {
  CallId,
  createAssistantMessage,
  createToolResultMessage,
  createUserMessage,
} from '@deepseek-ai/dsh-llm'
import type { GenerateOptions, Message, ToolSchema } from '@deepseek-ai/dsh-llm'
import { renderRequest } from '../src/render.ts'
import { MCP_SERVER_NAME, toolOffer } from '../src/tools.ts'

const EXECUTABLE = '/opt/node22/bin/claude'
const STEPS = 10

/** ~600 characters, the size of a real harness system prompt's opening. */
const SYSTEM = [
  'You are a coding agent working inside a repository harness. You have exactly one tool,',
  'probe_read, which reads a file and returns its contents. Work one step at a time: on every',
  'turn, call probe_read exactly once for the next file you need, and say one short sentence about',
  'why. Never answer from memory, never guess a file\'s contents, and never call more than one tool',
  'in a turn. Do not summarize the whole task; do not produce a final report until you have read',
  'every file the task names. Keep your prose under two sentences per turn. The harness executes',
  'each call and returns its result to you on the following turn.',
].join(' ')

/** ~2000 characters, the size of a real task prompt with repository context. */
const TASK = [
  'Audit the request-rendering path of the provider package in this repository and report every',
  'place where a model-visible input is produced that the session log cannot reconstruct.',
  'The package renders a harness request into a product query: a system prompt slot, a single',
  'prompt text carrying the whole conversation under tag framing, and a set of native tool',
  'declarations served over an in-process protocol server. Read the files in this order and do not',
  'skip any: src/render.ts, src/tools.ts, src/response.ts, src/adapter.ts, src/config.ts,',
  'src/process.ts, src/types.ts, src/index.ts, tests/render.spec.ts, tests/adapter.spec.ts.',
  'For each file, state in one sentence what model-visible input it authors and whether that input',
  'is derived purely from the request the seam handed over. Pay attention to defaults applied',
  'inside the rendering rather than at the resolve step, to any constant text that reaches the',
  'model without a corresponding logged event, and to any place where the product wraps harness',
  'text with text of its own. The harness records a request header containing the system prompt,',
  'the tool schemas, and the message list; anything the model reads that is not in that header is',
  'a finding. Treat the product\'s own system-prompt envelope as a known finding and do not repeat',
  'it for every file. When you have read all ten files, produce a numbered list of findings, each',
  'naming the file, the input, and why the log cannot reconstruct it, followed by the smallest',
  'change that would close the gap. Do not propose changes that alter the seam\'s streaming chunk',
  'protocol or the one-response-per-request contract, and do not propose giving the product its',
  'own agent loop. Start now with src/render.ts.',
].join(' ')

const TOOL: ToolSchema = {
  name: 'probe_read',
  description: 'Read one file from the repository and return its full contents.',
  parameters: {
    type: 'object',
    properties: { path: { type: 'string', description: 'Repository-relative path.' } },
    required: ['path'],
  },
}

const FILES = [
  'src/render.ts',
  'src/tools.ts',
  'src/response.ts',
  'src/adapter.ts',
  'src/config.ts',
  'src/process.ts',
  'src/types.ts',
  'src/index.ts',
  'tests/render.spec.ts',
  'tests/adapter.spec.ts',
]

/** A canned tool result of 1-3 KB, deterministic per step. */
function cannedResult(step: number): string {
  const header = `// ${FILES[step] ?? 'src/unknown.ts'} — ${1500 + step * 100} bytes\n`
  const body = Array.from({ length: 26 + step }, (_, line) =>
    `export function step${step}Line${line}(input: string): string {\n`
    + `  // deterministic filler so each result is a realistic 1-3 KB of source text\n`
    + `  return input.repeat(${line + 1}).slice(0, ${64 + line})\n`
    + `}\n`).join('')
  return header + body
}

interface StepSample {
  readonly step: number
  readonly cacheWrite: number
  readonly cacheRead: number
  readonly input: number
  readonly output: number
  readonly ms: number
  readonly calledTool: boolean
  readonly subtype: string
}

interface DesignResult {
  readonly design: string
  readonly samples: StepSample[]
  readonly wallMs: number
  readonly processStarts: number
  readonly note: string
}

/** The route's fixed SDK options, minus the continuity fields each design sets. */
function baseOptions(systemPrompt: string, offer: ReturnType<typeof toolOffer>): Options {
  return {
    cwd: process.cwd(),
    pathToClaudeCodeExecutable: EXECUTABLE,
    systemPrompt,
    includePartialMessages: true,
    permissionMode: 'dontAsk',
    tools: [],
    allowedTools: offer === undefined ? [] : [...offer.allowedTools],
    disallowedTools: ['AskUserQuestion'],
    mcpServers: offer === undefined ? {} : { [MCP_SERVER_NAME]: offer.server },
    strictMcpConfig: true,
    settingSources: [],
  }
}

function usageOf(message: Extract<SDKMessage, { type: 'result' }>): {
  cacheWrite: number
  cacheRead: number
  input: number
  output: number
} {
  const usage = message.usage as Record<string, number | undefined>
  return {
    cacheWrite: usage['cache_creation_input_tokens'] ?? 0,
    cacheRead: usage['cache_read_input_tokens'] ?? 0,
    input: usage['input_tokens'] ?? 0,
    output: usage['output_tokens'] ?? 0,
  }
}

function toolUseIn(messages: readonly SDKMessage[]): { name: string; input: unknown } | undefined {
  for (const message of messages) {
    if (message.type !== 'assistant') continue
    for (const block of message.message.content) {
      if (typeof block === 'object' && block !== null && (block as { type?: string }).type === 'tool_use') {
        return block as unknown as { name: string; input: unknown }
      }
    }
  }
  return undefined
}

/** Design A: today's route. Fresh query per step, whole conversation re-rendered. */
async function designA(): Promise<DesignResult> {
  const offer = toolOffer([TOOL])
  const samples: StepSample[] = []
  const messages: Message[] = [
    createUserMessage({ source: { kind: 'user' }, content: [{ type: 'text', text: TASK }] }),
  ]
  const startedAt = Date.now()
  let processStarts = 0
  for (let step = 0; step < STEPS; step += 1) {
    const request = { provider: 'probe', model: 'default', system: SYSTEM, messages } as GenerateOptions
    const rendered = renderRequest(request)
    const stepStart = Date.now()
    const controller = new AbortController()
    const running = query({
      prompt: rendered.prompt,
      options: { ...baseOptions(rendered.systemPrompt, offer), maxTurns: 1, persistSession: false, abortController: controller },
    })
    processStarts += 1
    const collected: SDKMessage[] = []
    let result: Extract<SDKMessage, { type: 'result' }> | undefined
    for await (const message of running) {
      collected.push(message)
      if (message.type === 'result') result = message
    }
    running.close()
    if (result === undefined) throw new Error(`design A step ${step}: no result`)
    const call = toolUseIn(collected)
    samples.push({
      step,
      ...usageOf(result),
      ms: Date.now() - stepStart,
      calledTool: call !== undefined,
      subtype: result.subtype,
    })
    const callId = CallId(`probe-a-${step}`)
    messages.push(createAssistantMessage({
      source: { provider: 'probe', model: 'default' },
      content: [
        { type: 'text', text: `Reading ${FILES[step] ?? 'the next file'}.` },
        { type: 'tool-call', id: callId, name: TOOL.name, arguments: JSON.stringify({ path: FILES[step] }) },
      ],
    }))
    messages.push(createToolResultMessage({
      callId,
      isError: false,
      content: [{ type: 'text', text: cannedResult(step) }],
    }))
  }
  await offer?.close()
  return {
    design: 'A (today: fresh query per step, whole conversation re-rendered)',
    samples,
    wallMs: Date.now() - startedAt,
    processStarts,
    note: 'persistSession: false',
  }
}

/** Design B: one product session per harness session, resumed per step. */
async function designB(): Promise<DesignResult> {
  const offer = toolOffer([TOOL])
  const samples: StepSample[] = []
  const startedAt = Date.now()
  let processStarts = 0
  let sessionId: string | undefined
  const seenSessions = new Set<string>()
  for (let step = 0; step < STEPS; step += 1) {
    const first = step === 0
    const request = {
      provider: 'probe',
      model: 'default',
      system: SYSTEM,
      messages: [createUserMessage({ source: { kind: 'user' }, content: [{ type: 'text', text: TASK }] })],
    } as GenerateOptions
    const rendered = renderRequest(request)
    const prompt = first
      ? rendered.prompt
      : `<dsh-tool-result id="probe-b-${step - 1}" status="ok">\n${cannedResult(step - 1)}\n</dsh-tool-result>\n`
    const stepStart = Date.now()
    const controller = new AbortController()
    const running = query({
      prompt,
      options: {
        ...baseOptions(rendered.systemPrompt, offer),
        maxTurns: 1,
        persistSession: true,
        abortController: controller,
        ...first || sessionId === undefined ? {} : { resume: sessionId },
      },
    })
    processStarts += 1
    const collected: SDKMessage[] = []
    let result: Extract<SDKMessage, { type: 'result' }> | undefined
    for await (const message of running) {
      collected.push(message)
      if (message.type === 'result') result = message
    }
    running.close()
    if (result === undefined) throw new Error(`design B step ${step}: no result`)
    sessionId = result.session_id
    seenSessions.add(result.session_id)
    const call = toolUseIn(collected)
    samples.push({
      step,
      ...usageOf(result),
      ms: Date.now() - stepStart,
      calledTool: call !== undefined,
      subtype: result.subtype,
    })
  }
  await offer?.close()
  return {
    design: 'B (one product session, resumed per step)',
    samples,
    wallMs: Date.now() - startedAt,
    processStarts,
    note: `persistSession: true; distinct product session ids: ${seenSessions.size} (${[...seenSessions].join(', ')})`,
  }
}

/** A pushable async iterable of SDK user messages, for streaming-input mode. */
class MessageFeed implements AsyncIterable<SDKUserMessage> {
  private readonly queued: SDKUserMessage[] = []
  private waiting: ((value: IteratorResult<SDKUserMessage>) => void) | undefined
  private ended = false

  push(text: string): void {
    const message: SDKUserMessage = {
      type: 'user',
      message: { role: 'user', content: [{ type: 'text', text }] },
      parent_tool_use_id: null,
      session_id: '',
    } as unknown as SDKUserMessage
    if (this.waiting !== undefined) {
      const resolve = this.waiting
      this.waiting = undefined
      resolve({ value: message, done: false })
      return
    }
    this.queued.push(message)
  }

  end(): void {
    this.ended = true
    if (this.waiting !== undefined) {
      const resolve = this.waiting
      this.waiting = undefined
      resolve({ value: undefined as unknown as SDKUserMessage, done: true })
    }
  }

  [Symbol.asyncIterator](): AsyncIterator<SDKUserMessage> {
    return {
      next: (): Promise<IteratorResult<SDKUserMessage>> => {
        const queued = this.queued.shift()
        if (queued !== undefined) return Promise.resolve({ value: queued, done: false })
        if (this.ended) {
          return Promise.resolve({ value: undefined as unknown as SDKUserMessage, done: true })
        }
        return new Promise((resolve) => { this.waiting = resolve })
      },
    }
  }
}

/** Design C: one query, the conversation as an async iterable of user messages. */
async function designC(maxTurns: number): Promise<DesignResult> {
  const offer = toolOffer([TOOL])
  const samples: StepSample[] = []
  const startedAt = Date.now()
  const feed = new MessageFeed()
  const request = {
    provider: 'probe',
    model: 'default',
    system: SYSTEM,
    messages: [createUserMessage({ source: { kind: 'user' }, content: [{ type: 'text', text: TASK }] })],
  } as GenerateOptions
  const rendered = renderRequest(request)
  const controller = new AbortController()
  const running = query({
    prompt: feed,
    options: {
      ...baseOptions(rendered.systemPrompt, offer),
      maxTurns,
      persistSession: false,
      abortController: controller,
    },
  })
  feed.push(rendered.prompt)
  let step = 0
  let stepStart = Date.now()
  let calledTool = false
  const iterator = running[Symbol.asyncIterator]()
  try {
    while (step < STEPS) {
      const next = await iterator.next()
      if (next.done === true) break
      const message = next.value
      if (message.type === 'assistant') {
        for (const block of message.message.content) {
          if ((block as { type?: string }).type === 'tool_use') calledTool = true
        }
      }
      if (message.type !== 'result') continue
      samples.push({
        step,
        ...usageOf(message),
        ms: Date.now() - stepStart,
        calledTool,
        subtype: message.subtype,
      })
      step += 1
      calledTool = false
      stepStart = Date.now()
      if (step < STEPS) {
        feed.push(
          `<dsh-tool-result id="probe-c-${step - 1}" status="ok">\n${cannedResult(step - 1)}\n</dsh-tool-result>\n`,
        )
      }
    }
  } finally {
    feed.end()
    running.close()
    await offer?.close()
  }
  return {
    design: `C (one query, async-iterable user messages, maxTurns: ${maxTurns})`,
    samples,
    wallMs: Date.now() - startedAt,
    processStarts: 1,
    note: 'persistSession: false',
  }
}

function report(result: DesignResult): void {
  const write = result.samples.reduce((sum, sample) => sum + sample.cacheWrite, 0)
  const read = result.samples.reduce((sum, sample) => sum + sample.cacheRead, 0)
  const output = result.samples.reduce((sum, sample) => sum + sample.output, 0)
  console.log(`\n### ${result.design}`)
  console.log(`note: ${result.note}`)
  console.log('step | cache write | cache read | input | output | ms | tool call | subtype')
  for (const sample of result.samples) {
    console.log(
      `${sample.step} | ${sample.cacheWrite} | ${sample.cacheRead} | ${sample.input} | `
      + `${sample.output} | ${sample.ms} | ${String(sample.calledTool)} | ${sample.subtype}`,
    )
  }
  const share = write + read === 0 ? 0 : Math.round((read / (write + read)) * 100)
  console.log(
    `TOTAL steps=${result.samples.length} write=${write} read=${read} output=${output} `
    + `read-share=${share}% wall=${result.wallMs}ms starts=${result.processStarts}`,
  )
  console.log(`JSON ${JSON.stringify({ design: result.design, write, read, output, share, wallMs: result.wallMs, starts: result.processStarts, samples: result.samples })}`)
}

function projectsFootprint(): string {
  try {
    return execFileSync('du', ['-sb', `${process.env['HOME'] ?? '/root'}/.claude/projects`], { encoding: 'utf8' }).trim()
  } catch {
    return 'unavailable'
  }
}

const which = process.argv[2] ?? 'A'
console.log(`footprint before: ${projectsFootprint()}`)
const chosen = which === 'A'
  ? await designA()
  : which === 'B'
    ? await designB()
    : await designC(Number(process.argv[3] ?? '1'))
report(chosen)
console.log(`footprint after: ${projectsFootprint()}`)
process.exit(0)

