/**
 * Drain one query, keeping the published result when the SDK throws afterwards
 * — the turn bound is this route's normal terminal for a tool-calling reply.
 */
async function drain(running: ReturnType<typeof query>): Promise<{
  result: Extract<SDKMessage, { type: 'result' }>
  collected: SDKMessage[]
}> {
  const collected: SDKMessage[] = []
  let result: Extract<SDKMessage, { type: 'result' }> | undefined
  try {
    for await (const message of running) {
      collected.push(message)
      if (message.type === 'result') result = message
    }
  } catch (error: unknown) {
    if (result === undefined) throw new Error(`query failed: ${(error as Error).message}`)
  }
  running.close()
  if (result === undefined) throw new Error('query ended without a result')
  return { result, collected }
}

